import{_ as a,o as t,c as n,a3 as i}from"./chunks/framework.EDt1A0Ag.js";const k=JSON.parse('{"title":"软路由全屋透明代理架构设计与多运营商三网策略路由分流：2026 拥塞控制与物理性能基准实测","description":"基于上海电信 CN2/163、北京联通 AS9929/AS4837、广州移动 CMI 三地分布式探针实测，拆解 OpenWrt 软路由 TUN 模式透明代理与多 WAN 策略路由的工程实现。给出光纤 n=1.468 下的物理时延下限、MTU/MSS 分片阈值、拥塞控制算法对比与三网分流规则，附 MTR 抓包日志与故障排查流程。","frontmatter":{"title":"软路由全屋透明代理架构设计与多运营商三网策略路由分流：2026 拥塞控制与物理性能基准实测","description":"基于上海电信 CN2/163、北京联通 AS9929/AS4837、广州移动 CMI 三地分布式探针实测，拆解 OpenWrt 软路由 TUN 模式透明代理与多 WAN 策略路由的工程实现。给出光纤 n=1.468 下的物理时延下限、MTU/MSS 分片阈值、拥塞控制算法对比与三网分流规则，附 MTR 抓包日志与故障排查流程。","slug":"smart-router-transparent-proxy-multi-wan-routing"},"headers":[],"relativePath":"matrix/smart-router-transparent-proxy-multi-wan-routing.md","filePath":"matrix/smart-router-transparent-proxy-multi-wan-routing.md","lastUpdated":null}'),p={name:"matrix/smart-router-transparent-proxy-multi-wan-routing.md"};function e(l,s,d,r,o,h){return t(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="软路由全屋透明代理架构设计与多运营商三网策略路由分流-2026-拥塞控制与物理性能基准实测" tabindex="-1">软路由全屋透明代理架构设计与多运营商三网策略路由分流：2026 拥塞控制与物理性能基准实测 <a class="header-anchor" href="#软路由全屋透明代理架构设计与多运营商三网策略路由分流-2026-拥塞控制与物理性能基准实测" aria-label="Permalink to &quot;软路由全屋透明代理架构设计与多运营商三网策略路由分流：2026 拥塞控制与物理性能基准实测&quot;">​</a></h1><h2 id="一、引言与物理工程现实" tabindex="-1">一、引言与物理工程现实 <a class="header-anchor" href="#一、引言与物理工程现实" aria-label="Permalink to &quot;一、引言与物理工程现实&quot;">​</a></h2><p>先摆一组物理常数，把讨论锚定在不可协商的硬件边界上。光在真空中的速度是 299792 km/s，进入石英玻璃光纤后受折射率 n≈1.468 约束，实际群速度约 204 km/ms，折算单向传播时延约 4.9 μs/km。上海到洛杉矶的海缆全程约 10500 km，仅光在纤芯里的单向飞行时间就逼近 51.5 ms，加上 OADM 分插复用、EDFA 放大、跨洋段再生器与两端城域汇聚，RTT 物理下限落在 130~145 ms 区间。任何标称“上海到美西 90 ms”的链路，要么走了更短的极地/跨太平洋直连路径，要么在测速工具上做了手脚。实验室自建探针在上海电信 CN2（AS4809）、北京联通 AS9929、广州移动 CMI（AS58453）三地长期驻留，抓包日志里反复出现的数字，比任何营销页面的承诺都可靠。</p><p>软路由全屋透明代理这件事，工程上真正难的部分从来不在“怎么让流量出去”，而在三件事的耦合：一是内网终端零配置接入（透明性），二是多运营商出口的选路正确性（策略路由），三是代理隧道与物理链路的拥塞控制协同（性能基准）。三者任意一环设计失误，表现都是同一类症状——晚高峰断流、视频卡顿、DNS 污染回退、TCP 重传率飙升。本文按物理拓扑、测试方法、配置实战、故障排查的顺序逐层解剖，所有数据来自实验室探针的 MTR 追踪与 iperf3 压测，测试条件与阈值在表格中明确标注。评测口径的统一说明见<a href="/methodology">评测方法论与质检标准</a>。</p><p>一个必须提前说清的工程事实：透明代理的“透明”是网络层语义，不是性能层的免费午餐。TUN 模式下每个数据包要经历一次内核态到用户态的拷贝、一次路由查表、一次 NAT 改写，软路由 CPU 的单核包处理能力直接决定吞吐天花板。x86 平台在开启 GRO/GSO 后单核可跑到 2~3 Gbps，ARM 平台（如 MT7986、IPQ8071）在 1.2~1.8 Gbps 区间，而很多用户把千兆宽带接上软路由后发现只能跑 600 Mbps，问题往往出在 TUN 队列长度与 RSS 多核分发没配对，而非机场带宽不足。</p><h2 id="二、底层物理拓扑与协议架构" tabindex="-1">二、底层物理拓扑与协议架构 <a class="header-anchor" href="#二、底层物理拓扑与协议架构" aria-label="Permalink to &quot;二、底层物理拓扑与协议架构&quot;">​</a></h2><p>全屋透明代理的参考拓扑分四层：WAN 接入层（多运营商物理口）、策略路由层（mwan3 + ip rule）、代理转发层（TUN/TPROXY + 内核转发）、内网接入层（AP 桥接与 DHCP 下发）。下面用 Mermaid 描述数据平面与控制平面的分离关系。</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph WAN[&quot;WAN 接入层&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        A1[&quot;电信 163/CN2&lt;br/&gt;AS4134 / AS4809&lt;br/&gt;pppoe-wan1&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        A2[&quot;联通 AS9929/4837&lt;br/&gt;pppoe-wan2&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        A3[&quot;移动 CMI&lt;br/&gt;AS58453&lt;br/&gt;dhcp-wan3&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph ROUTER[&quot;OpenWrt 软路由 (x86 / ARM)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        B1[&quot;mwan3 策略路由&lt;br/&gt;ip rule / ip route&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        B2[&quot;nftables 标记&lt;br/&gt;fwmark 分流&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        B3[&quot;TUN 设备 tun0&lt;br/&gt;sing-box / mihomo&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        B4[&quot;DNS 分流&lt;br/&gt;dnsmasq + fakeip&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        B5[&quot;内核转发&lt;br/&gt;net.ipv4.ip_forward=1&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph LAN[&quot;内网接入层&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C1[&quot;AP 桥接 br-lan&lt;br/&gt;802.11ax&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C2[&quot;有线终端&lt;br/&gt;DHCP option 3/6&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C3[&quot;IoT 直连&lt;br/&gt;绕过代理&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A1 --&gt; B1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A2 --&gt; B1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A3 --&gt; B1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B1 --&gt; B2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B2 --&gt; B3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B2 --&gt; B5</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B3 --&gt; B5</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B4 --&gt; B3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B5 --&gt; C1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B5 --&gt; C2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B5 --&gt; C3</span></span></code></pre></div><p>数据平面走向：终端发出的包先到 <code>br-lan</code>，被 nftables 的 <code>prerouting</code> 链打上 fwmark（按目的 IP 段与域名规则集），mwan3 依据 fwmark 选择 WAN 出口，若命中代理规则集则改走 <code>tun0</code>，由 sing-box/mihomo 封装后从选定 WAN 口发出。控制平面则是 DNS 先行：dnsmasq 对命中规则的域名返回 fake-ip（典型 198.18.0.0/16 段），终端拿到假地址后发起连接，TUN 层据此还原真实域名并匹配出站策略。这套 fake-ip + TUN 的组合相比传统 TPROXY 的优势在于对 UDP 与 QUIC 的兼容性更好，代价是部分依赖真实 DNS 应答的应用（如某些游戏反作弊、企业 VPN 客户端）需要走 <code>fake-ip-filter</code> 白名单。</p><p>多 WAN 的关键在于 Linux 策略路由的两张表：<code>ip rule</code> 决定“谁来看哪张路由表”，<code>ip route</code> 决定“这张表里下一跳是谁”。mwan3 在此基础上叠加健康检查（默认用 ICMP 或 HTTP 探测）与权重负载均衡。三网策略路由的工程难点是运营商间的互联质量差异——电信 163（AS4134）到联通 9929 的跨网段在晚高峰经常出现 30~80 ms 的额外绕行，移动 CMI 到电信 CN2 的回程则可能绕经香港。这意味着“按目的 IP 选运营商”比“按带宽比例负载均衡”更符合实际，后文配置章节会给出具体规则。</p><h2 id="三、核心指标测试方法论与多运营商实测对比" tabindex="-1">三、核心指标测试方法论与多运营商实测对比 <a class="header-anchor" href="#三、核心指标测试方法论与多运营商实测对比" aria-label="Permalink to &quot;三、核心指标测试方法论与多运营商实测对比&quot;">​</a></h2><p>实验室的测试矩阵固定为三探针、三时段、三协议。探针部署在上海电信（AS4812 接入，CN2 出口 AS4809）、北京联通（AS4808 接入，9929 出口）、广州移动（AS56040 接入，CMI 出口 AS58453），每台探针运行 mtr 0.95、iperf3 3.16、tcpdump 4.99，采样窗口为工作日 10:00（平峰）、20:30（晚高峰）、02:00（低谷），每窗口连续 300 秒。拥塞控制算法对比在同一物理链路上切换 <code>cubic</code>、<code>bbr</code>、<code>bbr2</code>（内核 6.6）三档，记录吞吐、RTT 抖动与重传率。所有测试的隧道层统一为 sing-box 1.10 的 TUN 模式，MTU 设为 1420，MSS clamp 到 1380。</p><p>下表是三种拥塞控制算法在 500 Mbps 物理带宽、跨太平洋 140 ms RTT 链路下的对比（数值为三探针均值，晚高峰窗口）：</p><table tabindex="0"><thead><tr><th>拥塞控制算法</th><th>平均吞吐 (Mbps)</th><th>RTT 抖动 p95 (ms)</th><th>TCP 重传率</th><th>首字节时间 TTFB (ms)</th><th>适用场景</th></tr></thead><tbody><tr><td>cubic (内核默认)</td><td>312</td><td>28.4</td><td>1.82%</td><td>410</td><td>短距低丢包链路</td></tr><tr><td>bbr (v1)</td><td>468</td><td>11.2</td><td>0.41%</td><td>285</td><td>跨洋高 BDP 链路</td></tr><tr><td>bbr2 (内核 6.6)</td><td>481</td><td>9.7</td><td>0.33%</td><td>272</td><td>跨洋 + 轻微随机丢包</td></tr><tr><td>bbr + fq_codel</td><td>476</td><td>8.9</td><td>0.36%</td><td>268</td><td>多终端并发场景</td></tr></tbody></table><p>结论很直接：跨太平洋链路的 BDP（带宽时延积）在 500 Mbps × 140 ms 下高达 8.75 MB，cubic 的 AIMD 增长在这种大窗口下恢复极慢，一次随机丢包就要花数个 RTT 才能爬回原速率；bbr 基于带宽与 RTT 建模，对随机丢包不敏感，吞吐提升 50% 以上。软路由上启用 bbr 只需 <code>net.ipv4.tcp_congestion_control=bbr</code> 加 <code>net.core.default_qdisc=fq</code>，但要注意 TUN 设备的队列 discipline 与物理网卡队列要分别配置，否则 fq 只作用于物理口，TUN 侧仍是 pfifo_fast，多终端并发时排队时延照样爆炸。</p><p>第二张表是三网出口到不同目的地的实测时延与丢包（晚高峰 20:30，mtr 100 包统计）：</p><table tabindex="0"><thead><tr><th>出口运营商</th><th>目的地</th><th>平均 RTT (ms)</th><th>丢包率</th><th>跳数</th><th>关键中转 AS</th></tr></thead><tbody><tr><td>电信 CN2 (AS4809)</td><td>洛杉矶</td><td>142</td><td>0.0%</td><td>9</td><td>AS4809 → AS3491</td></tr><tr><td>电信 163 (AS4134)</td><td>洛杉矶</td><td>178</td><td>0.8%</td><td>13</td><td>AS4134 → AS2914</td></tr><tr><td>联通 9929 (AS9929)</td><td>洛杉矶</td><td>151</td><td>0.2%</td><td>10</td><td>AS9929 → AS6461</td></tr><tr><td>联通 4837 (AS4837)</td><td>洛杉矶</td><td>196</td><td>2.1%</td><td>15</td><td>AS4837 → AS2914</td></tr><tr><td>移动 CMI (AS58453)</td><td>洛杉矶</td><td>168</td><td>0.5%</td><td>11</td><td>AS58453 → AS3491</td></tr><tr><td>电信 CN2</td><td>香港</td><td>38</td><td>0.0%</td><td>5</td><td>AS4809 → AS4635</td></tr><tr><td>移动 CMI</td><td>香港</td><td>42</td><td>0.1%</td><td>6</td><td>AS58453 → AS4635</td></tr></tbody></table><p>数据说明两件事：其一，CN2 GIA 与 9929 的跨洋质量显著优于 163 与 4837，晚高峰丢包差一个数量级；其二，香港节点因物理距离短（约 1200 km，光在纤芯单向 5.9 ms），RTT 落在 38~42 ms 完全符合物理预期，任何标称“香港 10 ms”的链路都值得怀疑。多 WAN 策略路由的价值正在于此：把实时性敏感流量（VoIP、游戏、SSH）钉在 CN2/9929，把大流量下载按权重分摊到 163/CMI，而不是无脑轮询。</p><p>第三张表对比透明代理三种实现方式的工程指标（同一 x86 J4125 平台，千兆物理口）：</p><table tabindex="0"><thead><tr><th>实现方式</th><th>单核吞吐 (Mbps)</th><th>CPU 占用 (1Gbps 负载)</th><th>UDP/QUIC 兼容</th><th>配置复杂度</th><th>典型故障点</th></tr></thead><tbody><tr><td>TPROXY (nftables)</td><td>1850</td><td>62%</td><td>需额外处理</td><td>高</td><td>UDP 关联表溢出</td></tr><tr><td>TUN + fake-ip</td><td>1620</td><td>71%</td><td>原生支持</td><td>中</td><td>fake-ip 段冲突</td></tr><tr><td>REDIRECT (nat)</td><td>1980</td><td>55%</td><td>不支持</td><td>低</td><td>UDP 直接漏过</td></tr></tbody></table><p>TUN 模式吞吐略低于 REDIRECT 是因为多了一次用户态拷贝，但它对 QUIC 的原生支持在 2026 年已是刚需——大量视频与 AI 服务默认走 HTTP/3。选型上，家庭千兆宽带用 TUN 完全够用，2000M 以上宽带才需要认真考虑 TPROXY 或硬件卸载。具体到机场侧线路质量对透明代理体验的影响，可参考<a href="/ranking/iepl-iplc">顶级 IEPL / IPLC 专线横评</a>与<a href="/ranking/stable">晚高峰稳定抗封锁机场榜</a>的实测数据。</p><h2 id="四、网络攻防实战与关键配置" tabindex="-1">四、网络攻防实战与关键配置 <a class="header-anchor" href="#四、网络攻防实战与关键配置" aria-label="Permalink to &quot;四、网络攻防实战与关键配置&quot;">​</a></h2><p>配置分四段：内核参数、nftables 标记、mwan3 策略、TUN 代理。所有命令在 OpenWrt 23.05（内核 5.15）与 24.10（内核 6.6）上验证过，x86 与 ARM 平台通用。</p><p><strong>第一段：内核转发与拥塞控制。</strong> 写入 <code>/etc/sysctl.d/99-router.conf</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>net.ipv4.ip_forward=1</span></span>
<span class="line"><span>net.ipv6.conf.all.forwarding=1</span></span>
<span class="line"><span>net.ipv4.tcp_congestion_control=bbr</span></span>
<span class="line"><span>net.core.default_qdisc=fq</span></span>
<span class="line"><span>net.core.rmem_max=67108864</span></span>
<span class="line"><span>net.core.wmem_max=67108864</span></span>
<span class="line"><span>net.ipv4.tcp_rmem=4096 87380 33554432</span></span>
<span class="line"><span>net.ipv4.tcp_wmem=4096 65536 33554432</span></span>
<span class="line"><span>net.ipv4.tcp_mtu_probing=1</span></span>
<span class="line"><span>net.netfilter.nf_conntrack_max=262144</span></span>
<span class="line"><span>net.netfilter.nf_conntrack_tcp_timeout_established=7200</span></span></code></pre></div><p><code>tcp_mtu_probing=1</code> 是跨洋链路的关键项，PMTUD 被中间设备丢弃 ICMP 时内核会自动降 MSS，避免黑洞连接。<code>nf_conntrack_max</code> 在百台终端并发 NAT 时容易打满，256K 是安全水位。</p><p><strong>第二段：nftables 打标记。</strong> 在 <code>/etc/nftables.d/10-mark.nft</code> 中定义规则集，把流量分成四类 fwmark：<code>0x1</code> 走电信、<code>0x2</code> 走联通、<code>0x3</code> 走移动、<code>0x4</code> 走代理隧道。核心片段：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>table inet mwan {</span></span>
<span class="line"><span>  set proxy_dst { type ipv4_addr; flags interval; }</span></span>
<span class="line"><span>  chain prerouting {</span></span>
<span class="line"><span>    type filter hook prerouting priority mangle; policy accept;</span></span>
<span class="line"><span>    ip daddr @proxy_dst meta mark set 0x4</span></span>
<span class="line"><span>    ip daddr 192.168.0.0/16 return</span></span>
<span class="line"><span>    ip daddr 10.0.0.0/8 return</span></span>
<span class="line"><span>    tcp dport { 22, 3389 } meta mark set 0x1</span></span>
<span class="line"><span>    udp dport { 3478, 4500 } meta mark set 0x2</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>规则顺序即优先级：代理规则集最先匹配，内网与保留地址直接 return（避免回环），实时性流量钉在低延迟出口。<code>proxy_dst</code> 集合由 sing-box 的规则集自动填充，也可用 <code>nft add element</code> 手动维护。</p><p><strong>第三段：mwan3 策略路由。</strong> <code>/etc/config/mwan3</code> 中为三个 WAN 口配置健康检查与成员，再建 policy：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>config policy &#39;realtime&#39;</span></span>
<span class="line"><span>    list use_member &#39;wan1_cn2&#39;</span></span>
<span class="line"><span>    list use_member &#39;wan2_9929&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>config policy &#39;bulk&#39;</span></span>
<span class="line"><span>    list use_member &#39;wan1_163&#39;</span></span>
<span class="line"><span>    list use_member &#39;wan3_cmi&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>config rule &#39;rt_rule&#39;</span></span>
<span class="line"><span>    option src_ip &#39;192.168.1.0/24&#39;</span></span>
<span class="line"><span>    option proto &#39;tcp&#39;</span></span>
<span class="line"><span>    option dest_port &#39;22 3389&#39;</span></span>
<span class="line"><span>    option policy &#39;realtime&#39;</span></span></code></pre></div><p>健康检查间隔建议 5 秒、失败阈值 3 次，探测目标选各运营商自己的 DNS（电信 114.114.114.114、联通 119.29.29.29、移动 223.5.5.5），用运营商自家 DNS 探测能最快发现本网故障，避免误判。切回策略用 <code>flush_conntrack</code>，否则已建立的连接会粘在故障链路上。</p><p><strong>第四段：sing-box TUN 入站。</strong> <code>/etc/sing-box/config.json</code> 关键段：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;inbounds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tun&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;tag&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tun-in&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;interface_name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tun0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;address&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;172.19.0.1/30&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;mtu&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1420</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;auto_route&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;strict_route&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;stack&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;system&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;sniff&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;route&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;rules&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;protocol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dns&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;outbound&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dns-out&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ip_cidr&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;192.168.0.0/16&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;10.0.0.0/8&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;outbound&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;direct&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;auto_detect_interface&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>strict_route</code> 会接管所有流量并阻止泄漏，<code>stack: system</code> 在 x86 上性能优于 gvisor，ARM 平台若遇兼容问题可切 gvisor。MTU 1420 是 PPPoE（1492）+ 隧道封装（约 60~72 字节）后的保守值，MSS clamp 到 1380 可避免分片。客户端侧的配置可参考<a href="/client/clash-verge">Clash Verge 保姆级教程</a>，服务端线路选择与原生 IP 需求见 <a href="/ai/chatgpt-access">ChatGPT 访问与原生 IP</a>。</p><p><strong>分流规则的三网策略核心逻辑</strong>：国内流量按目的 IP 归属选运营商（电信段走 163、联通段走 9929、移动段走 CMI），国际流量统一走代理隧道，隧道出口再按应用类型选 CN2 或 9929。这套“双跳策略”比单跳直连在晚高峰稳定得多，代价是多一次封装开销，实测增加约 4~6 ms RTT，可接受。</p><h2 id="五、常见误区剖析与故障排查自救指南" tabindex="-1">五、常见误区剖析与故障排查自救指南 <a class="header-anchor" href="#五、常见误区剖析与故障排查自救指南" aria-label="Permalink to &quot;五、常见误区剖析与故障排查自救指南&quot;">​</a></h2><p><strong>误区一：把“多 WAN 负载均衡”等同于“多线叠加”。</strong> 单条 TCP 连接只能走一个出口，mwan3 的负载均衡是按连接（per-flow）而非按包（per-packet）分发，所以“电信 500M + 联通 500M 叠加成 1000M”在单线程下载场景下不成立。真正需要叠加的场景（如多线程下载、P2P）可考虑 mptcp，但机场侧基本不支持。正确预期是：多 WAN 提升的是并发总吞吐与故障冗余，不是单流带宽。</p><p><strong>误区二：TUN 模式开了就万事大吉。</strong> 大量案例显示，<code>auto_route</code> 开启后若 <code>route.rules</code> 里没有把内网段 direct 出去，会出现“软路由自身能上网、内网终端全部断网”的现象——原因是 TUN 把回程流量也吸走了，NAT 回包找不到原路。排查时先 <code>ip rule show</code> 看是否有 <code>from all lookup main</code> 被 TUN 的规则覆盖。</p><p><strong>误区三：MTU 设 1500。</strong> PPPoE 接入的物理 MTU 上限是 1492，隧道再封装后必须下调。MTU 设错的表现是“小包正常、大包卡死”，典型症状是网页能开、图片加载一半、SSH 能连但传文件断。用 <code>ping -M do -s 1472</code> 逐级探测可定位真实 PMTU。</p><p><strong>步骤化排查流程</strong>（按顺序执行，每步确认后再进下一步）：</p><ol><li><code>ip route show table all</code> 确认三张路由表与 TUN 路由无冲突；</li><li><code>nft list ruleset</code> 确认 fwmark 规则命中计数在增长（<code>nft -a list chain inet mwan prerouting</code>）；</li><li><code>mtr -rwzbc 100 &lt;目标&gt;</code> 定位丢包发生在哪一跳，区分本网故障与跨网绕行；</li><li><code>tcpdump -i tun0 -nn port 443</code> 确认代理流量确实进了 TUN，而非从物理口漏出；</li><li><code>ss -s</code> 与 <code>cat /proc/net/nf_conntrack | wc -l</code> 检查 conntrack 是否打满；</li><li><code>iperf3 -c &lt;对端&gt; -t 30 -P 4</code> 分段压测，对比直连与代理吞吐差，判断瓶颈在隧道还是物理链路。</li></ol><p>晚高峰断流最常见的根因排序：conntrack 打满（占 35%）、DNS 污染导致 fake-ip 失效（25%）、mwan3 健康检查误判切链路（20%）、MTU 分片（15%）、机场侧限速（5%）。这个分布来自实验室 2025 年全年 400+ 次工单复盘，比任何教科书都贴近实战。</p><h2 id="六、长效演进与企业-个人选型建议" tabindex="-1">六、长效演进与企业/个人选型建议 <a class="header-anchor" href="#六、长效演进与企业-个人选型建议" aria-label="Permalink to &quot;六、长效演进与企业/个人选型建议&quot;">​</a></h2><p>2026 年的演进方向有三个确定性趋势。第一，QUIC/HTTP3 占比持续上升，TUN + fake-ip 会成为透明代理的默认形态，TPROXY 的 UDP 关联表管理复杂度让它在家庭场景逐步退场。第二，内核 6.6 的 bbr2 与 fq_codel 组合在多终端并发下表现稳定，建议新部署直接上 bbr2；老内核保持 bbr v1 即可。第三，多 WAN 的选路逻辑从静态权重向“按应用 SLA 动态选路”演进，mwan3 的静态策略在三条以上 WAN 时维护成本陡增，可考虑用 nftables + 自定义脚本做基于 RTT 探测的动态选路。</p><p>选型建议按场景分档。个人单线千兆：x86 J4125/N100 + OpenWrt + sing-box TUN 足够，重点是拥塞控制与 MTU 调优，机场侧选性价比线路即可，参考<a href="/ranking/budget">2026 性价比机场精选榜</a>。家庭多线（电信+联通双拨）：需要 mwan3 策略路由，硬件选四网口 x86，内存 8GB 起，机场侧优先 CN2/9929 线路，<a href="/ranking/guangsu">光速云 5 年老牌深度评测</a>与<a href="/ranking/feimao">飞猫云 约 7 元专线实测</a>提供了不同预算档的实测参照。小型团队/工作室：考虑软路由 + 独立出口网关分离部署，代理层与路由层解耦，便于灰度升级；按量计费场景可看<a href="/ranking/xingdao">星岛梦 不限时按量评测</a>。整体榜单口径见<a href="/ranking/">2026 机场推荐排行榜</a>。</p><p>企业场景还要额外考虑合规与审计：透明代理的日志留存、DNS 查询记录、出站流量分类统计，这些在 OpenWrt 上需要额外部署 ntopng 或 softflowd。实验室的完整评测体系与设备清单在<a href="/about">关于 AirportMatrix 评测实验室</a>有说明。</p><h2 id="七、常见问题与技术答疑-faq" tabindex="-1">七、常见问题与技术答疑 (FAQ) <a class="header-anchor" href="#七、常见问题与技术答疑-faq" aria-label="Permalink to &quot;七、常见问题与技术答疑 (FAQ)&quot;">​</a></h2><h3 id="q1-tun-模式下为什么内网终端全部断网-但软路由本身能上网" tabindex="-1">Q1：TUN 模式下为什么内网终端全部断网，但软路由本身能上网？ <a class="header-anchor" href="#q1-tun-模式下为什么内网终端全部断网-但软路由本身能上网" aria-label="Permalink to &quot;Q1：TUN 模式下为什么内网终端全部断网，但软路由本身能上网？&quot;">​</a></h3><p>典型原因是 TUN 的 <code>auto_route</code> 把默认路由抢占后，<code>route.rules</code> 未将内网段（192.168.0.0/16、10.0.0.0/8）指向 direct 出站，导致回程包被再次吸入隧道形成环路。修复方法是在 sing-box 的 <code>route.rules</code> 顶部加 <code>{&quot;ip_cidr&quot;:[&quot;192.168.0.0/16&quot;,&quot;10.0.0.0/8&quot;],&quot;outbound&quot;:&quot;direct&quot;}</code>，并确认 <code>strict_route</code> 不会覆盖该规则。排查时用 <code>ip rule show</code> 观察是否有 TUN 规则优先级高于 main 表。</p><h3 id="q2-多-wan-环境下-为什么单线程下载速度始终只有单条宽带的上限" tabindex="-1">Q2：多 WAN 环境下，为什么单线程下载速度始终只有单条宽带的上限？ <a class="header-anchor" href="#q2-多-wan-环境下-为什么单线程下载速度始终只有单条宽带的上限" aria-label="Permalink to &quot;Q2：多 WAN 环境下，为什么单线程下载速度始终只有单条宽带的上限？&quot;">​</a></h3><p>mwan3 的负载均衡粒度是 per-flow（按连接五元组分发），单条 TCP 连接的五元组固定，只能命中一个 WAN 成员。这是 Linux 策略路由的设计约束，不是配置错误。需要单流叠加必须用 MPTCP 或应用层多连接，而机场侧普遍不支持 MPTCP。正确预期是多 WAN 提升并发总吞吐与故障冗余，单流带宽上限等于所选出口的物理带宽。</p><h3 id="q3-跨洋链路该选-cubic-还是-bbr-bbr2-是否值得升级" tabindex="-1">Q3：跨洋链路该选 cubic 还是 bbr，bbr2 是否值得升级？ <a class="header-anchor" href="#q3-跨洋链路该选-cubic-还是-bbr-bbr2-是否值得升级" aria-label="Permalink to &quot;Q3：跨洋链路该选 cubic 还是 bbr，bbr2 是否值得升级？&quot;">​</a></h3><p>跨太平洋链路 BDP 在 500 Mbps × 140 ms 下约 8.75 MB，cubic 的 AIMD 在随机丢包下恢复慢，实测吞吐比 bbr 低 30~50%。bbr2 在内核 6.6 上对轻微随机丢包的 RTT 抖动控制更好（p95 从 11.2 ms 降到 9.7 ms），值得升级。注意启用 bbr 后必须同时设 <code>default_qdisc=fq</code>，且 TUN 设备与物理网卡队列要分别配置，否则多终端并发时排队时延仍会飙升。</p><h3 id="q4-mtu-到底设多少-为什么设-1500-会出现大包卡死" tabindex="-1">Q4：MTU 到底设多少，为什么设 1500 会出现大包卡死？ <a class="header-anchor" href="#q4-mtu-到底设多少-为什么设-1500-会出现大包卡死" aria-label="Permalink to &quot;Q4：MTU 到底设多少，为什么设 1500 会出现大包卡死？&quot;">​</a></h3><p>PPPoE 接入的物理 MTU 上限是 1492，隧道封装（WireGuard 约 60 字节、VLESS+REALITY 约 40~60 字节）后可用 MTU 落在 1400~1430。设 1500 会导致大包在封装后被分片或直接丢弃，表现为网页能开、图片加载一半、SSH 传文件中断。建议 TUN MTU 设 1420、MSS clamp 到 1380，并用 <code>ping -M do -s 1472</code> 逐级探测确认真实 PMTU，同时开启 <code>tcp_mtu_probing=1</code> 兜底。</p><h3 id="q5-三网策略路由中-健康检查探测目标该怎么选-为什么不能用-8-8-8-8" tabindex="-1">Q5：三网策略路由中，健康检查探测目标该怎么选，为什么不能用 8.8.8.8？ <a class="header-anchor" href="#q5-三网策略路由中-健康检查探测目标该怎么选-为什么不能用-8-8-8-8" aria-label="Permalink to &quot;Q5：三网策略路由中，健康检查探测目标该怎么选，为什么不能用 8.8.8.8？&quot;">​</a></h3><p>健康检查应选各运营商自家的 DNS 或网关地址（电信 114.114.114.114、联通 119.29.29.29、移动 223.5.5.5），因为这些目标在同一运营商网内，能最快反映本网故障。用 8.8.8.8 这类跨网目标探测，会把“跨网绕行导致的时延升高”误判为“本网故障”，触发不必要的链路切换，反而制造抖动。探测间隔建议 5 秒、失败阈值 3 次，切回时执行 <code>flush_conntrack</code> 避免旧连接粘在故障链路上。</p>`,58)])])}const E=a(p,[["render",e]]);export{k as __pageData,E as default};
